# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜKÛN SEBEBİYLE OLUŞAN MEDLERİN KARŞILAŞTIRMALI ŞEMASI (KK.6.2.1)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Medd-i Lâzım</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#1e3a8a">• Harf-i medden (ا، و، ي) sonra</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Lâzım Sükûn (cezim/şedde)</text>\n  <text x="125" y="132" text-anchor="middle" font-size="11" fill="#1e3a8a">gelmesiyle oluşur.</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">• Durulsa da geçilse de sükûn</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">bozulmaz; hükmü vaciptir.</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#2563eb">Uzatma: 4 Elif (Kesin)</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Örnek: الضَّالِّينَ ، الْحَاقَّةُ ، الم</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Medd-i Ârız</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#14532d">• Harf-i medden sonra kelime</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">sonunda Ârız (Geçici) Sükûn</text>\n  <text x="350" y="132" text-anchor="middle" font-size="11" fill="#14532d">gelmesiyle (durulduğunda) oluşur.</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#14532d">• Geçildiğinde Medd-i Tabiîye</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#14532d">dönüşür; hükmü caizdir.</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Uzatma: 1 ile 4 Elif arası</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Örnek: الْعَالَمِينَ ➔ الْعَالَمِينْ</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Medd-i Lîn</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#713f12">• Üstünlü harften sonra gelen</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">cezimli Vav (ـَوْ) veya Yâ (ـَيْ)</text>\n  <text x="575" y="132" text-anchor="middle" font-size="11" fill="#713f12">(Lîn harfi) sonrası sükûnla oluşur.</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#713f12">• Yumuşak bir sesle uzatılır;</text>\n  <text x="575" y="172" text-anchor="middle" font-size="11" fill="#713f12">geçildiğinde uzatılmaz.</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">Uzatma: Durunca 1–4 Elif</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#713f12">Örnek: قُرَيْشٍ ، الصَّيْفِ ، خَوْفٍ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">LÂZIM SÜKÛN İLE ÂRIZ (GEÇİCİ) SÜKÛN FARKI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Lâzım (Aslî / Kalıcı) Sükûn</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11.5" fill="#155e75">• Kelimenin aslında var olan cezim (ـْ)</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11.5" fill="#155e75">veya şedde (ـّ) işaretidir.</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11.5" fill="#155e75">• Kelime üzerinde durulsa da (vakıf)</text>\n  <text x="182" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">okumaya devam edilse de (vasıl) sükûn</text>\n  <text x="182" y="182" text-anchor="middle" font-size="11.5" fill="#155e75">ortadan kalkmaz.</text>\n  <text x="182" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0e7490">الضَّالِّينَ ، الصَّاخَّةُ ، الْآنَ ➔ Medd-i Lâzım</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Ârız (Geçici) Sükûn</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11.5" fill="#9d174d">• Normalde harekeli olan son harfin,</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11.5" fill="#9d174d">durak (vakıf) yapıldığı için cezimli</text>\n  <text x="517" y="138" text-anchor="middle" font-size="11.5" fill="#9d174d">okunmasıyla ortaya çıkan geçici sükûndur.</text>\n  <text x="517" y="164" text-anchor="middle" font-size="11.5" fill="#9d174d">• Durulmadan geçilirse sükûn kalkar ve</text>\n  <text x="517" y="182" text-anchor="middle" font-size="11.5" fill="#9d174d">kural 1 eliflik Medd-i Tabiî olur.</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be185d">نَسْتَعِينُ (durunca: نَسْتَعِينْ) ➔ Medd-i Ârız</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HARF-İ MED İLE HARF-İ LÎN AYRIMI VE BAKARA 106-134 UYGULAMASI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Harf-i Med (تَعْلَمُونَ / الرَّحِيمِ)</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Vav (و) sakin, önceki harf ÖTRELİ (ـُو)</text>\n  <text x="182" y="124" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Yâ (ي) sakin, önceki harf ESRELİ (ـِي)</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Elif (ا) sakin, önceki harf ÜSTÜNLÜ (ـَا)</text>\n  <text x="182" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Durulduğunda ➔ Medd-i Ârız olur:</text>\n  <text x="182" y="200" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">الْعَلِيمُ ، الْحَكِيمُ ، تَعْلَمُونَ ، يُؤْمِنُونَ</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Harf-i Lîn (قُرَيْشٍ / خَوْفٍ)</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11.5" fill="#581c87">• Vav (وْ) cezimli, önceki harf ÜSTÜNLÜ (ـَوْ)</text>\n  <text x="517" y="124" text-anchor="middle" font-size="11.5" fill="#581c87">• Yâ (يْ) cezimli, önceki harf ÜSTÜNLÜ (ـَيْ)</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11.5" fill="#581c87">• («ev» ve «ey» sesi verir, yumuşak okunur)</text>\n  <text x="517" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Durulduğunda ➔ Medd-i Lîn olur:</text>\n  <text x="517" y="200" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">الْبَيْتِ ، قُرَيْشٍ ، الصَّيْفِ ، خَوْفٍ ، يَوْمٍ</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
